document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,a="info"){return`\n      <div class="insight-card ${a}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const a=document.getElementById("bnb-form"),t=document.getElementById("bnb-result");a&&a.addEventListener("submit",function(a){a.preventDefault();const i=parseInt(document.getElementById("rooms").value),o=parseFloat(document.getElementById("property-cost").value),r=parseFloat(document.getElementById("renovation-cost").value),l=parseFloat(document.getElementById("additional-costs").value),d=parseFloat(document.getElementById("avg-nightly-rate").value),c=parseFloat(document.getElementById("high-season-occupancy").value),p=parseFloat(document.getElementById("low-season-occupancy").value),v=parseFloat(document.getElementById("high-season-months").value),u=parseFloat(document.getElementById("staff-costs").value),g=parseFloat(document.getElementById("utilities").value),m=parseFloat(document.getElementById("marketing").value),b=parseFloat(document.getElementById("other-expenses").value);if(i<=0||d<=0||c<=0||p<=0)return t.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const w=o+r+l,h=12-v,y=c/100,$=p/100,f=30*i*y*d,k=30*i*$*d,B=f*v,I=k*h,E=B+I,F=.12*E,A=E+F,R=u+g+m+b,P=12*R,x=A-P,L=x/12,D=x/A*100,M=w/x,O=x/w*100,S=A/i,C=(y*v+$*h)/12,T=30*i*12*d,H=E/T*100;let U="info";x<0?U="warning":D>30&&(U="success");let j="info";O<15?j="warning":O>25&&(j="success");let V="info";C<.5?V="warning":C>.7&&(V="success"),t.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🏨 Bed & Breakfast Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n(w),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(L),`Margin: ${e(D)}`,U)}\n            ${s("⏱️ Payback Period",`${M.toFixed(1)} years`,`ROI: ${e(O)}`,M<=5?"success":"warning")}\n            ${s("🛏️ Occupancy Rate",e(100*C),"Annual average",V)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Property (purchase/down payment)</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Renovation & furnishing</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licenses, permits & equipment</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(w)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Annual Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>High season (${v} months × ${e(c)})</span>\n                  <span>${n(B)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Low season (${h} months × ${e(p)})</span>\n                  <span>${n(I)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Additional services (breakfast, transfers)</span>\n                  <span>${n(F)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Annual Revenue</strong></span>\n                  <span><strong>${n(A)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Staff (housekeeping, front desk)</span>\n                  <span>${n(u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Utilities (electric, water, internet)</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Marketing & platform commissions</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(b)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(R)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🔄 Room Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per room: <strong>${n(S)}/year</strong><br>\n                Average nightly rate: <strong>${n(d)}/night</strong><br>\n                Revenue efficiency: <strong>${e(H)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${x>0?"success":"warning"}">\n              <h6>📊 Seasonal Analysis</h6>\n              <div class="metric-subtitle">\n                High season: <strong>${n(f)}/month</strong><br>\n                Low season: <strong>${n(k)}/month</strong><br>\n                Seasonal variance: <strong>${e((f-k)/k*100)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${L>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(x)}</strong><br>\n                Weekly profit: <strong>${n(x/52)}</strong><br>\n                Daily profit: <strong>${n(x/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Growth Potential</h6>\n              <div class="metric-subtitle">\n                Maximum revenue: <strong>${n(T)}/year</strong><br>\n                Growth reserve: <strong>${e(100-H)}</strong><br>\n                At 100% occupancy: <strong>+${n(T-E)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${D<20?"<li>⚠️ Low profitability. Consider increasing rates or reducing costs.</li>":""}\n              ${C<.5?"<li>📍 Low occupancy. Improve marketing or adjust pricing strategy.</li>":""}\n              ${M>6?"<li>⏰ Long payback period. Optimize startup costs or increase revenue.</li>":""}\n              ${C>.8?"<li>✅ High occupancy! Consider rate increases or expansion.</li>":""}\n              ${D>30?"<li>🎉 Excellent profitability! Consider additional properties.</li>":""}\n              <li>🍳 Add breakfast and meal services to increase revenue by 15-25%.</li>\n              <li>📱 Optimize presence on Booking.com, AirBnB, and own website.</li>\n              <li>🎯 Implement dynamic pricing based on seasonality and demand.</li>\n              <li>🚗 Consider additional services: transfers, tours, laundry.</li>\n              <li>🤝 Partner with tour operators and corporate clients.</li>\n              <li>⭐ Invest in guest review improvement to boost online ratings.</li>\n              <li>💳 Offer package deals and loyalty programs for repeat guests.</li>\n              <li>🌐 Develop direct booking channels to avoid platform commissions.</li>\n              <li>🎪 Host events and workshops during low season to increase occupancy.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.bnbBusinessData={"Number of Rooms":i,"Total Investment ($)":w,"Annual Revenue ($)":A,"Annual Expenses ($)":P,"Annual Profit ($)":x,"Monthly Profit ($)":L,"Profit Margin (%)":D,"Annual ROI (%)":O,"Payback Period (years)":M,"Average Occupancy (%)":100*C,"Revenue per Room ($)":S,"Average Nightly Rate ($)":d}}),window.downloadCSV=function(){if(!window.bnbBusinessData)return;const n=Object.entries(window.bnbBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="bnb-business-plan.csv",s.click()}});